-- ===========================================================================
-- Sporta database accounts and privileges — GENERATED by ops/db/make-grants.mjs.
-- Do not edit by hand. Change the PHP or make-grants.mjs and regenerate;
-- `npm run test:db-least-privilege` fails when this file and the code disagree.
--
-- WHAT THIS IS. The web application used to connect with one broad account.
-- This file creates the narrow ones: each actor gets exactly the table and
-- column privileges the code can use, and none of: DROP, GRANT OPTION, FILE,
-- PROCESS, RELOAD, SUPER, LOCK TABLES, CREATE TEMPORARY TABLES, TRIGGER, EVENT,
-- EXECUTE, CREATE ROUTINE, CREATE VIEW — and, for every account but the
-- migration one, none of CREATE, ALTER or INDEX either. (The code sends no DDL,
-- no LOCK TABLES and no temporary tables; scripts/lib/php-sql-map.php lists
-- every statement.) The tables of the old storefront build, which no code here
-- reads, are granted to nobody except the read-only backup account.
--
-- HOW TO RUN IT. NEVER feed this file to the client as it is: it holds
-- placeholders (@@DB@@, @@APP_HOST@@, @@JOB_HOST@@, @@HASH_<ACCOUNT>@@).
--   node ops/db/render-grants.mjs --db sporta --app-host <net> --job-host <net> \
--        --secrets <dir> --generate | mariadb ...
-- fills them in, generates the passwords on the machine that runs it (0600 files,
-- never printed), sends the SERVER only the password HASH (so no log of the server
-- can hold a password) and refuses a wildcard host. The guard just below makes the
-- client stop at once if this file is piped in unrendered. See ops/db/README.md.
--
-- ONE BLOCK PER ACCOUNT (BEGIN ACCOUNT / END ACCOUNT). Each block creates the
-- account if it is missing, empties its privileges and grants the exact set again,
-- so a block converges on this file and nothing else. render-grants.mjs can emit
-- chosen blocks only (--only) and can leave out the empty-then-grant step
-- (--additive), which is how a LIVE account is re-applied without a moment in which
-- it has no privilege at all (measured: the empty-then-grant window of the whole
-- file is seconds, and every in-use account gets "access denied" in it).
--
-- Accounts are created LOCKED. Nothing can sign in as one until a person
-- unlocks it (render-grants.mjs --activate ... at creation, --unlock later), so an
-- account that is never used stays unusable.
-- ===========================================================================

-- Guard: stops here (error 1242) unless render-grants.mjs rendered this file.
SELECT IF(@sporta_rendered = 1, 1, (SELECT 1 UNION ALL SELECT 2)) AS render_grants_first;

-- BEGIN ACCOUNT web
-- ------------------------------------------------------------------------
-- sporta_web
-- ONE account for the whole web runtime and the host cron jobs (api, admin, customer, crm, assistant, SEO, birthday, cron-*). Needs no code change: it replaces db_user/db_pass.
-- code roles: shop + admin + cron
CREATE USER IF NOT EXISTS 'sporta_web'@'@@APP_HOST@@' IDENTIFIED VIA mysql_native_password USING '@@HASH_WEB@@'
  WITH MAX_USER_CONNECTIONS 100 ACCOUNT LOCK;
-- Anything an earlier run (or a person) granted is removed before the exact set below is granted again.
REVOKE ALL PRIVILEGES, GRANT OPTION FROM 'sporta_web'@'@@APP_HOST@@';
ALTER USER 'sporta_web'@'@@APP_HOST@@' WITH MAX_USER_CONNECTIONS 100;
-- admin_activity_log: written by store#store_admin_event, store#store_system_event
GRANT SELECT, INSERT ON `@@DB@@`.`admin_activity_log` TO 'sporta_web'@'@@APP_HOST@@';
-- admin_password_resets: written by admin#(top)
GRANT SELECT, INSERT, DELETE ON `@@DB@@`.`admin_password_resets` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (used_at) ON `@@DB@@`.`admin_password_resets` TO 'sporta_web'@'@@APP_HOST@@';
-- admin_recovery_codes: written by store#store_recovery_claim, store#store_recovery_replace
GRANT SELECT, INSERT, DELETE ON `@@DB@@`.`admin_recovery_codes` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (used_at) ON `@@DB@@`.`admin_recovery_codes` TO 'sporta_web'@'@@APP_HOST@@';
-- admin_users: written by admin#(top), store#store_admin_grant
GRANT SELECT ON `@@DB@@`.`admin_users` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (failed_attempts, google_sub, last_login_at, locked_until, must_change_password, password_hash, temporary_password_expires_at, temporary_password_used_at, totp_enabled, totp_last_step, totp_secret) ON `@@DB@@`.`admin_users` TO 'sporta_web'@'@@APP_HOST@@';
-- blocked_customers: written by admin#(top)
GRANT SELECT, INSERT, DELETE ON `@@DB@@`.`blocked_customers` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (blocked_by, phone, reason, scope) ON `@@DB@@`.`blocked_customers` TO 'sporta_web'@'@@APP_HOST@@';
-- brands: written by admin#(top)
GRANT SELECT, INSERT, DELETE ON `@@DB@@`.`brands` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (active, name_ar, name_en, slug, sort) ON `@@DB@@`.`brands` TO 'sporta_web'@'@@APP_HOST@@';
-- crm_contacts: written by crm#crm_save
GRANT SELECT, INSERT ON `@@DB@@`.`crm_contacts` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (contact_key, created_by, display_name, follow_up_at, status, tags_json, updated_at, updated_by) ON `@@DB@@`.`crm_contacts` TO 'sporta_web'@'@@APP_HOST@@';
-- crm_notes: written by crm#crm_add_note
GRANT SELECT, INSERT ON `@@DB@@`.`crm_notes` TO 'sporta_web'@'@@APP_HOST@@';
-- customer_accounts: written by birthday#(top), cron-birthday#(top), customer#(top), customer-auth#customer_insert, customer-auth#customer_profile_update
GRANT SELECT, INSERT, UPDATE ON `@@DB@@`.`customer_accounts` TO 'sporta_web'@'@@APP_HOST@@';
-- customer_password_resets: written by customer#(top)
GRANT SELECT, INSERT ON `@@DB@@`.`customer_password_resets` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (used_at) ON `@@DB@@`.`customer_password_resets` TO 'sporta_web'@'@@APP_HOST@@';
-- discounts: written by admin#(top), cron-birthday#(top), store#store_discount_release, store#store_discounts_claim, store#store_review_reward
GRANT SELECT, INSERT, DELETE, UPDATE ON `@@DB@@`.`discounts` TO 'sporta_web'@'@@APP_HOST@@';
-- fulfilment_outbox: written by cron-fulfilment#(top), store#store_fulfilment_reinstate, store#store_queue_fulfilment
GRANT SELECT, INSERT ON `@@DB@@`.`fulfilment_outbox` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (attempts, last_error, sent_at) ON `@@DB@@`.`fulfilment_outbox` TO 'sporta_web'@'@@APP_HOST@@';
-- hero_slides: written by admin#(top)
GRANT SELECT, INSERT, DELETE, UPDATE ON `@@DB@@`.`hero_slides` TO 'sporta_web'@'@@APP_HOST@@';
-- inventory_movements: written by admin#(top)
GRANT SELECT, INSERT ON `@@DB@@`.`inventory_movements` TO 'sporta_web'@'@@APP_HOST@@';
-- order_items: written by api#(top)
