-- support_messages: written by support#support_admin_reply, support#support_create
GRANT SELECT, INSERT ON `@@DB@@`.`support_messages` TO 'sporta_web'@'@@APP_HOST@@';
-- support_tickets: written by support#support_admin_reply, support#support_admin_update, support#support_create, support#support_customer_reply
GRANT SELECT, INSERT ON `@@DB@@`.`support_tickets` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (assigned_to, last_customer_at, last_staff_at, priority, resolved_at, status) ON `@@DB@@`.`support_tickets` TO 'sporta_web'@'@@APP_HOST@@';
-- whatsapp_outbox: written by cron-whatsapp#(top), store#store_queue_whatsapp
GRANT SELECT, INSERT ON `@@DB@@`.`whatsapp_outbox` TO 'sporta_web'@'@@APP_HOST@@';
GRANT UPDATE (attempts, last_error, sent_at, wa_message_id) ON `@@DB@@`.`whatsapp_outbox` TO 'sporta_web'@'@@APP_HOST@@';
